# %%
from math import factorial, log, sqrt, exp
from scipy.special import binom

eta = 0.3
dims_per_nat = 2 * ((1 + sqrt(eta)) ** 2) / (1 - eta + (1 / log(1000_000)))
dims_per_bit = dims_per_nat * log(2)
print(eta, dims_per_nat, dims_per_bit)
